"""Generated by the QA agent for STORY-103: Transfer between my own accounts."""
from playwright.sync_api import expect

from nilebank_helpers import money


def test_tc_103_01_own_transfer_moves_money_ui(signed_in, amira):
    """TC-103-01 (UI)"""
    page = signed_in
    page.get_by_test_id("nav-transfer").click()
    page.get_by_test_id("transfer-from").select_option("CUR-1001")
    page.get_by_test_id("transfer-to").select_option("acc:SAV-1002")
    page.get_by_test_id("transfer-amount-input").fill("2500.75")
    page.get_by_test_id("transfer-submit").click()
    expect(page.get_by_test_id("transfer-success")).to_be_visible()
    assert money(page.get_by_test_id("transfer-amount").inner_text()) == 2500.75
    assert amira.balance("CUR-1001") == 22499.25
    assert amira.balance("SAV-1002") == 102500.75


def test_tc_103_02_insufficient_funds_refused_api(amira):
    """TC-103-02 (API)"""
    r = amira.post("/api/transfers", json={"from_account": "CUR-1001", "to_account": "SAV-1002", "amount": 30000})
    assert r.status_code == 409, r.text
    assert "Insufficient funds" in r.json()["detail"]
    assert amira.balance("CUR-1001") == 25000.00 and amira.balance("SAV-1002") == 100000.00


def test_tc_103_03_zero_and_negative_amounts_refused_api(amira):
    """TC-103-03 (API)"""
    for amount in (0, -50):
        r = amira.post("/api/transfers", json={"from_account": "CUR-1001", "to_account": "SAV-1002", "amount": amount})
        assert r.status_code == 422, f"amount {amount}: {r.status_code} {r.text}"


def test_tc_103_04_same_account_refused_api(amira):
    """TC-103-04 (API)"""
    r = amira.post("/api/transfers", json={"from_account": "CUR-1001", "to_account": "CUR-1001", "amount": 10})
    assert r.status_code == 422, r.text
